const SECRET_KEYS = { tracking: ['metaCapiToken'], integrations: ['metaAdsToken'], couriers: ['apiToken', 'apiKey'], ai: ['geminiKey', 'openaiKey', 'cfApiToken'] };
const C = require('./couriers');
const SECTION_FOR_SETTING = { store: 'settings', theme: 'design', delivery: 'settings', costs: 'settings', fraud: 'settings', tracking: 'settings', integrations: 'settings', form: 'settings', couriers: 'settings' };
