const RESERVED = new Set(['admin', 'api', 'www', 'app', 'assets', 'uploads', 's', 'signup', 'login', 'register', 'platform', 'mail', 'static', 'cdn', 'health', 'support', 'help', 'blog', 'store-admin', 'root', 'test']);

