    if (key.startsWith('c_')) { o.type = ['text', 'textarea', 'select', 'number'].includes(x.type) ? x.type : 'text'; o.options = (Array.isArray(x.options) ? x.options : String(x.options || '').split(',')).map((v) => U.str(v, 40)).filter(Boolean).slice(0, 30); }
