  if (!email || !/^[^@\s]+@[^@\s]+$/.test(email)) throw U.httpError(400, 'Valid email required');
  if (!password || String(password).length < 8) throw U.httpError(400, 'Password must be at least 8 characters');
  if (await D.get('SELECT id FROM users WHERE email = ?', String(email).toLowerCase())) throw U.httpError(409, 'Email already used');
