    let rows;
    if (ids.length) rows = (await D.all(`SELECT * FROM orders WHERE store_id = ? AND id IN (${ids.map(() => '?').join(',')}) ORDER BY id`, sid, ...ids));
    else if (q.get('status')) rows = (await D.all('SELECT * FROM orders WHERE store_id = ? AND status = ? ORDER BY id', sid, q.get('status')));
    else rows = (await D.all('SELECT * FROM orders WHERE store_id = ? ORDER BY id DESC LIMIT 5000', sid));
