// Numbers are wrapped in Unicode isolates (LRI…PDI) so "3 900" never shows as "900 3" in Arabic pages.
const money = (n, t) => '\u2066' + String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '\u202f') + '\u2069 ' + t.currency;
const safeId = (s) => String(s || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 40);
const FONT_URLS = {
  Cairo: 'Cairo:wght@400;600;700;800;900', Tajawal: 'Tajawal:wght@400;500;700;800', Almarai: 'Almarai:wght@400;700;800', 'IBM Plex Sans Arabic': 'IBM+Plex+Sans+Arabic:wght@400;600;700',
  'Readex Pro': 'Readex+Pro:wght@300;400;600;700', 'El Messiri': 'El+Messiri:wght@400;600;700', 'Noto Kufi Arabic': 'Noto+Kufi+Arabic:wght@400;600;800', Changa: 'Changa:wght@400;600;800'
};

function hexA(hex, a) {
  const h = String(hex).replace('#', '');
  if (h.length !== 6) return `rgba(15,92,70,${a})`;
  return `rgba(${parseInt(h.slice(0, 2), 16)},${parseInt(h.slice(2, 4), 16)},${parseInt(h.slice(4, 6), 16)},${a})`;
}

function themeCss(th) {
  const r = Math.max(0, Math.min(28, Number(th.radius) || 0));
  return `:root{--p:${th.primary};--a:${th.accent};--ink:${th.ink};--bg:${th.bg};--r:${r}px;--rs:${Math.round(r * 0.65)}px;--p-soft:${hexA(th.primary, 0.12)};--p-faint:${hexA(th.primary, 0.06)};--a-soft:${hexA(th.accent, 0.16)};--font:'${th.font}',system-ui,sans-serif}`;
}

// All pixels of the store (+ the landing page's own pixel). Several Meta / TikTok pixels are supported.
function pixelList(tr, extra = {}) {
  const meta = [], tiktok = [];
  const addM = (id) => { id = safeId(id); if (id && !meta.includes(id)) meta.push(id); };
  const addT = (id) => { id = safeId(id); if (id && !tiktok.includes(id)) tiktok.push(id); };
  addM(extra.meta); addT(extra.tiktok);
  addM(tr.metaPixel); addT(tr.tiktokPixel);
  (tr.meta || []).forEach((x) => x && x.on !== false && addM(x.id));
  (tr.tiktok || []).forEach((x) => x && x.on !== false && addT(x.id));
  return { meta, tiktok, snap: safeId(tr.snapPixel), google: String(tr.googleTag || '').replace(/[^A-Za-z0-9-]/g, '').slice(0, 30) };
}
