function layout({ title, description = '', body, t, theme, store, pixels = {}, image = '', bodyClass = '' }) {
  const fontQ = FONT_URLS[theme.font] || FONT_URLS.Cairo;
  return `<!doctype html>
<html lang="${t.lang}" dir="${t.dir}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(description)}">
${image ? `<meta property="og:image" content="${esc(image)}">` : ''}
<meta name="theme-color" content="${esc(theme.primary)}">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=${fontQ}&display=swap" rel="stylesheet" media="print" onload="this.media='all'">
<link rel="stylesheet" href="/assets/store.css?v=7">
<style>${themeCss(theme)}</style>
${pixelHead(pixels.px, pixels.events)}
</head>
<body class="${bodyClass} th-${esc(String(theme.layout || 'classic').replace(/[^a-z]/g, ''))}">
${body}
</body>
</html>`;
}

function img(src, alt, cls = '', eager = false) {
  if (!src) return `<div class="ph ${cls}"><span>${esc(alt)}</span></div>`;
  return `<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async">`;
}

